pragma solidity >=0.8.0;

contract GasMeterLoopBoundary {
    uint8 public flag;
    uint256 public count;
    uint256 public lastResult;

    event Looped(uint256 n, uint256 result, uint256 count);

    function setFlag(uint8 v) external {
        flag = v;
    }

    function runLoop(uint256 n) external returns (uint256) {
        uint256 acc = 0;
        for (uint256 i = 0; i < n; i++) {
            unchecked {
                acc = acc + ((i * 3) + (acc / 5)) % 17;
            }
            if (i % 13 == 4) {
                continue;
            }
            if (i % 29 == 17) {
                unchecked {
                    acc = acc + 2;
                }
            }
        }
        unchecked {
            count = count + 1;
        }
        lastResult = acc;
        flag = uint8(acc);
        emit Looped(n, acc, count);
        return acc;
    }
}
